// Some portions generated by Claude
// Public topology: Zachary karate-club graph, unweighted, zero-based IDs.
// Cross-checked against NetworkX's published reference data:
// https://networkx.org/documentation/stable/_modules/networkx/generators/social.html#karate_club_graph
// This is a graph-layout fixture, not a claim that modularity recovers the two clubs.
export function karateNetwork() {
  const upper = [[1,2,3,4,5,6,7,8,10,11,12,13,17,19,21,31], [2,3,7,13,17,19,21,30], [3,7,8,9,13,27,28,32], [7,12,13],
    [6,10], [6,10,16], [16], [], [30,32,33], [33], [], [], [], [33], [32,33], [32,33], [], [], [32,33], [33],
    [32,33], [], [32,33], [25,27,29,32,33], [25,27,31], [31], [29,33], [33], [31,33], [32,33], [32,33], [32,33], [33], []];
  return network(34, upper.flatMap((neighbors, a) => neighbors.map(b => [a, b])), 'Member');
}

function network(count, pairs, label) {
  return {revision: 1, nodes: Array.from({length: count}, (_, i) => ({id: String(i), label: `${label} ${i}`, kind: 'iri', x: 0, y: 0})),
    edges: pairs.map(([a,b], i) => ({id: String(i), source: String(a), target: String(b), label: 'related', predicate: 'urn:related'}))};
}

export function cycleNetwork(count = 64) {
  return network(count, Array.from({length: count}, (_, i) => [i, (i + 1) % count]), 'Cycle');
}

export function bipartiteNetwork(size = 12) {
  return network(size * 2, Array.from({length: size}, (_, a) => Array.from({length: size}, (_, b) => [a, size + b])).flat(), 'Bipartite');
}

export function gridNetwork(size = 12) {
  const pairs = [];
  for (let i = 0; i < size * size; i++) {
    if (i % size) pairs.push([i - 1, i]);
    if (i >= size) pairs.push([i - size, i]);
  }
  return network(size * size, pairs, 'Grid');
}
